-- # Lernfeld 5: Cyberphysische Systeme > ## Qualitätssicherung > - Software anpassen

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann Software ohne Anpassung an neue Anforderungen langfristig ihre Qualität behalten?', 2, '[{"text": "Nein", "correct": true, "because": "Änderungen sind für Relevanz nötig"}, {"text": "Ja", "correct": false, "because": "Statische Software veraltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist jede Anpassung an einer Software automatisch mit einem Qualitätsverlust verbunden?', 2, '[{"text": "Nein", "correct": true, "because": "Qualität hängt von Umsetzung ab"}, {"text": "Ja", "correct": false, "because": "Anpassung kann Qualität steigern"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Softwareanpassungen ohne Tests sicher implementiert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Tests sichern Funktionalität"}, {"text": "Ja", "correct": false, "because": "Risiken ohne Tests hoch"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Anpassungen immer die gesamte Software betreffen?', 2, '[{"text": "Nein", "correct": true, "because": "Lokale Änderungen möglich"}, {"text": "Ja", "correct": false, "because": "Teilweise Anpassung üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Anpassung der Software ohne Dokumentation die Wartbarkeit beeinträchtigen?', 2, '[{"text": "Ja", "correct": true, "because": "Undokumentierte Änderungen erschweren"}, {"text": "Nein", "correct": false, "because": "Dokumentation ist entscheidend"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt ist bei der Softwareanpassung am wichtigsten, um Qualität zu sichern?', 2, '[{"text": "Testen", "correct": true, "because": "Überprüft Funktionalität"}, {"text": "Planung", "correct": false, "because": "Wichtig, aber nicht ausreichend"}, {"text": "Dokumentation", "correct": false, "because": "Unterstützend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode hilft, Anpassungen an bestehender Software strukturiert vorzunehmen?', 3, '[{"text": "Refactoring", "correct": true, "because": "Verbessert Struktur ohne Funktionsänderung"}, {"text": "Prototyping", "correct": false, "because": "Für Neuentwicklung"}, {"text": "Ad-hoc-Änderung", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Risiko tritt bei Softwareanpassungen ohne Rücksicht auf Abhängigkeiten auf?', 2, '[{"text": "Systeminstabilität", "correct": true, "because": "Abhängigkeiten können brechen"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Eher Verzögerung"}, {"text": "Kostenreduktion", "correct": false, "because": "Kosten steigen oft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt sollte bei der Anpassung besonders überwacht werden, um Fehler zu vermeiden?', 2, '[{"text": "Regressionsfehler", "correct": true, "because": "Änderungen können Altes beeinträchtigen"}, {"text": "Syntaxfehler", "correct": false, "because": "Leicht erkennbar"}, {"text": "Designfehler", "correct": false, "because": "Planungsebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug unterstützt die Qualitätssicherung bei Softwareanpassungen?', 2, '[{"text": "Versionskontrolle", "correct": true, "because": "Verfolgt Änderungen"}, {"text": "Texteditor", "correct": false, "because": "Nur Bearbeitung"}, {"text": "Compiler", "correct": false, "because": "Nur Übersetzung"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind bei der Anpassung von Software für Qualitätssicherung essenziell?', 4, '[{"text": "Anforderungsanalyse", "correct": true, "because": "Definiert Änderungsbedarf"}, {"text": "Testen nach Anpassung", "correct": true, "because": "Sichert Funktionalität"}, {"text": "Ad-hoc-Implementierung", "correct": false, "because": "Risikoreich"}, {"text": "Dokumentation der Änderungen", "correct": true, "because": "Erleichtert Wartung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken können bei Softwareanpassungen auftreten?', 3, '[{"text": "Regressionsfehler", "correct": true, "because": "Bestehende Funktionen beeinträchtigt"}, {"text": "Kompatibilitätsprobleme", "correct": true, "because": "Neue mit alter Software"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Eher Verlangsamung"}, {"text": "Erhöhte Komplexität", "correct": true, "because": "Struktur kann leiden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden unterstützen die Qualität bei Softwareanpassungen?', 3, '[{"text": "Unit-Tests", "correct": true, "because": "Überprüfen einzelne Module"}, {"text": "Refactoring", "correct": true, "because": "Verbessert Code-Struktur"}, {"text": "Manuelle Code-Änderung", "correct": false, "because": "Fehleranfällig"}, {"text": "Regressionstests", "correct": true, "because": "Sichern alte Funktionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Qualität von Softwareanpassungen?', 4, '[{"text": "Teamkompetenz", "correct": true, "because": "Erfahrung steigert Qualität"}, {"text": "Testabdeckung", "correct": true, "because": "Reduziert Fehler"}, {"text": "Zufällige Änderungen", "correct": false, "because": "Schadet Qualität"}, {"text": "Dokumentationsgrad", "correct": true, "because": "Erleichtert Nachvollziehbarkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine strukturierte Softwareanpassung?', 3, '[{"text": "Geringere Fehlerquote", "correct": true, "because": "Planung reduziert Risiken"}, {"text": "Bessere Wartbarkeit", "correct": true, "because": "Struktur bleibt klar"}, {"text": "Höhere Entwicklungskosten", "correct": false, "because": "Kosten können sinken"}, {"text": "Schnellere Implementierung", "correct": true, "because": "Effizienz steigt"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Softwareanpassungen ohne Tests erhöhen das Fehlerrisiko. b) Jede Anpassung verbessert die Softwarequalität automatisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tests essenziell, Qualität nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Refactoring ist bei jeder Softwareanpassung nötig. b) Versionskontrolle hilft, Änderungen nachzuverfolgen.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Refactoring optional, Versionskontrolle nützlich"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Softwareanpassungen können ohne Planung erfolgreich sein. b) Regressionstests sichern bestehende Funktionalität.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Planung wichtig, Regressionstests effektiv"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Dokumentation ist bei kleinen Anpassungen entbehrlich. b) Anpassungen können Kompatibilitätsprobleme verursachen.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Dokumentation immer hilfreich, Kompatibilität riskant"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Unit-Tests sind bei Softwareanpassungen unerlässlich. b) Schlecht geplante Anpassungen erhöhen die Komplexität.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Unit-Tests hilfreich aber optional, Komplexität steigt"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]');

